const issue = $('Prepare MAP issue fields').first().json;
const changelog = (issue && issue.changelog) || {};
const histories = changelog.histories || changelog.values || [];
const output = [];
for (let h = 0; h < histories.length; h++) {
  const history = histories[h] || {};
  const items = history.items || [];
  for (let itemIndex = 0; itemIndex < items.length; itemIndex++) {
    const item = items[itemIndex] || {};
    output.push({ json: {
      changelog_id: String(history.id),
      item_index: itemIndex,
      issue_key: issue.issue_key,
      issue_id: String(issue.issue_id),
      author_key: (history.author && (history.author.key || history.author.name)) || null,
      author_name: (history.author && history.author.displayName) || null,
      created_at: history.created || null,
      field: item.field || null,
      fieldtype: item.fieldtype || null,
      from_value: item.from || null,
      from_string: item.fromString || null,
      to_value: item.to || null,
      to_string: item.toString || null
    }});
  }
}
return output;

